<?php require_role('admin');require_once 'app/helpers.php';$page_title='Admin';include 'partials/header.php';$topics=db()->query('SELECT t.*,COUNT(s.id) sub_count FROM topics t LEFT JOIN subtopics s ON s.topic_id=t.id GROUP BY t.id ORDER BY t.audience,t.sort_order,t.id')->fetchAll();?><div class="row" style="justify-content:space-between"><h1>Knowledge Administration</h1><div class="actions"><a class="btn" href="admin_topic.php">+ Topic</a><a class="btn" href="admin_subtopic.php">+ Subtopic</a><a class="btn" href="admin_content.php">+ Content</a></div></div><div class="card table-wrap"><table><tr><th>Audience</th><th>Topic</th><th>Tamil</th><th>Subtopics</th><th>Actions</th></tr><?php foreach($topics as $t):?><tr><td><?=e($t['audience'])?></td><td><?=e($t['title_en'])?></td><td><?=e($t['title_ta'])?></td><td><?=e($t['sub_count'])?></td><td><a href="admin_topic.php?id=<?=$t['id']?>">Edit</a> · <a href="admin_subtopic.php?topic_id=<?=$t['id']?>">Add subtopic</a></td></tr><?php endforeach;?></table></div><?php include 'partials/footer.php';?>
